1	//! Pure logical-member audit over caller-acquired bounded bytes.
2	//! No file, publication, observation-history or durability authority is conferred.
3	use crate::{
4	    evidence::{self, Decoded, Kind, Record},
5	    evidence_attestation::{self as proof, Frontier, Purpose},
6	    evidence_copy_plan::Plan,
7	    evidence_recovery_commitment::{Counts, Domain, Header, Limits, MemberFraming},
8	    evidence_recovery_observation::Context,
9	    evidence_service as service,
10	    evidence_store::Committed,
11	};
12	use atproto_dasl::{Cid, Ipld};
13	use sha2::{Digest, Sha256};
14	use std::{
15	    collections::{BTreeMap, BTreeSet},
16	    sync::{
17	        atomic::{AtomicBool, Ordering},
18	        Arc,
19	    },
20	    time::{Duration, Instant},
21	};
22	const MAX_OBJECT: usize = 4 * 1024 * 1024;
23	type Result<T> = std::result::Result<T, Error>;
24	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
25	pub enum Error {
26	    #[error("invalid recovery member: {0}")]
27	    Invalid(&'static str),
28	    #[error("recovery member budget exhausted")]
29	    Budget,
30	    #[error("recovery member verification cancelled")]
31	    Cancelled,
32	}
33	fn framing_error(error: crate::evidence_recovery_commitment::Error) -> Error {
34	    use crate::evidence_recovery_commitment::Error as E;
35	    match error {
36	        E::Cancelled => Error::Cancelled,
37	        E::Budget => Error::Budget,
38	        E::Shape(_) | E::Poisoned => Error::Invalid("member framing"),
39	    }
40	}
41	fn require(ok: bool, reason: &'static str) -> Result<()> {
42	    if ok {
43	        Ok(())
44	    } else {
45	        Err(Error::Invalid(reason))
46	    }
47	}
48	#[derive(Clone)]
49	pub struct Budget {
50	    /// Sum of supplied record, membership and original-object rows.
51	    pub items: u64,
52	    /// Sum of input metadata/plan/payload bytes and canonical membership keys + lengths.
53	    /// Bounds retained metadata indirectly; this is not a measured RSS ceiling.
54	    pub input_bytes: u64,
55	    pub duration: Duration,
56	    pub cancelled: Arc<AtomicBool>,
57	}
58	#[derive(Clone, Copy)]
59	pub struct Row<'a> {
60	    pub sequence: u64,
61	    pub manifest: &'a [u8],
62	    pub receipt: &'a [u8],
63	    pub proof: &'a [u8],
64	}
65	#[derive(Clone, Copy)]
66	pub struct Object<'a> {
67	    pub cid: &'a Cid,
68	    pub bytes: &'a [u8],
69	}
70	#[derive(Clone, Copy)]
71	pub struct Membership<'a> {
72	    pub cid: &'a Cid,
73	    pub length: u64,
74	}
75	#[derive(Clone, Copy)]
76	pub struct Input<'a> {
77	    pub context: &'a Context,
78	    pub plan: Option<&'a [u8]>,
79	    pub membership: &'a [Membership<'a>],
80	    pub records: &'a [Row<'a>],
81	    pub objects: &'a [Object<'a>],
82	}
83	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
84	pub enum Availability {
85	    Available,
86	    Missing,
87	    Corrupt,
88	}
89	#[derive(Clone, Debug, PartialEq, Eq)]
90	pub struct Loss {
91	    pub occurrence: Option<u64>,
92	    pub cid: Cid,
93	    pub expected_length: Option<u64>,
94	    pub state: Availability,
95	}
96	/// Verified issuer metadata and sampled originals. Unavailable writer requests
97	/// remain unverified. This result is NOT an authenticated recovery history.
98	pub struct Member {
99	    context: Context,
100	    commitment: [u8; 32],
101	    frontier: Frontier,
102	    recipe_metadata_complete: bool,
103	    losses: Vec<Loss>,
104	    verified_requests: u64,
105	}
106	impl Member {
107	    pub fn context(&self) -> &Context {
108	        &self.context
109	    }
110	    pub fn commitment(&self) -> &[u8; 32] {
111	        &self.commitment
112	    }
113	    pub fn frontier(&self) -> &Frontier {
114	        &self.frontier
115	    }
116	    pub fn recipe_metadata_complete(&self) -> bool {
117	        self.recipe_metadata_complete
118	    }
119	    pub fn losses(&self) -> &[Loss] {
120	        &self.losses
121	    }
122	    pub fn verified_requests(&self) -> u64 {
123	        self.verified_requests
124	    }
125	}
126	struct Work {
127	    budget: Budget,
128	    deadline: Instant,
129	    bytes: u64,
130	}
131	impl Work {
132	    fn new(budget: Budget, items: usize) -> Result<Self> {
133	        require(
134	            !budget.duration.is_zero() && budget.duration <= Duration::from_secs(3600),
135	            "duration",
136	        )?;
137	        if u64::try_from(items).map_err(|_| Error::Budget)? > budget.items {
138	            return Err(Error::Budget);
139	        }
140	        let deadline = Instant::now()
141	            .checked_add(budget.duration)
142	            .ok_or(Error::Budget)?;
143	        let s = Self {
144	            budget,
145	            deadline,
146	            bytes: 0,
147	        };
148	        s.check()?;
149	        Ok(s)
150	    }
151	    fn check(&self) -> Result<()> {
152	        if self.budget.cancelled.load(Ordering::Relaxed) {
153	            return Err(Error::Cancelled);
154	        }
155	        if Instant::now() >= self.deadline {
156	            return Err(Error::Budget);
157	        }
158	        Ok(())
159	    }
160	    fn input(&mut self, size: usize) -> Result<()> {
161	        self.check()?;
162	        self.bytes = self.bytes.checked_add(size as u64).ok_or(Error::Budget)?;
163	        if self.bytes > self.budget.input_bytes {
164	            return Err(Error::Budget);
165	        }
166	        Ok(())
167	    }
168	    fn hash(&self, hash: &mut Sha256, bytes: &[u8]) -> Result<()> {
169	        for part in bytes.chunks(65536) {
170	            self.check()?;
171	            hash.update(part)
172	        }
173	        Ok(())
174	    }
175	    fn frame(&self, hash: &mut Sha256, bytes: &[u8]) -> Result<()> {
176	        hash.update((bytes.len() as u64).to_be_bytes());
177	        self.hash(hash, bytes)
178	    }
179	}
180	fn key(cid: &Cid) -> Result<String> {
181	    let b = cid.to_bytes();
182	    require(b.len() == 36 && b[..4] == [1, 0x55, 0x12, 0x20], "raw CID")?;
183	    Ok(cid.to_string())
184	}
185	fn ordered(last: &mut Option<String>, next: &str) -> Result<()> {
186	    require(
187	        last.as_ref().is_none_or(|x| x.as_str() < next),
188	        "CID order or duplicate",
189	    )?;
190	    *last = Some(next.into());
191	    Ok(())
192	}
193	fn known(bytes: &[u8], kind: Kind) -> Result<Record> {
194	    match evidence::decode(bytes).map_err(|_| Error::Invalid("metadata codec"))? {
195	        Decoded::Known(r) if r.kind() == kind => Ok(r),
196	        _ => Err(Error::Invalid("metadata profile")),
197	    }
198	}
199	struct Coordinate {
200	    cid: Cid,
201	    length: Option<u64>,
202	    referenced: bool,
203	    member: bool,
204	    original: Option<usize>,
205	    state: Availability,
206	}
207	fn length(c: &mut Coordinate, n: u64) -> Result<()> {
208	    require(
209	        (1..=MAX_OBJECT as u64).contains(&n),
210	        "forensic-recovery-required",
211	    )?;
212	    require(
213	        c.length.is_none_or(|old| old == n),
214	        "conflicting expected lengths",
215	    )?;
216	    c.length = Some(n);
217	    Ok(())
218	}
219	fn coordinate(cid: &Cid) -> Coordinate {
220	    Coordinate {
221	        cid: cid.clone(),
222	        length: None,
223	        referenced: false,
224	        member: false,
225	        original: None,
226	        state: Availability::Missing,
227	    }
228	}
229	fn did(s: &str) -> Result<()> {
230	    require(
231	        (56..=80).contains(&s.len()) && s.is_ascii() && s.starts_with("did:key:z"),
232	        "issuer encoding",
233	    )?;
234	    let (a, k) = atrium_crypto::did::parse_did_key(s).map_err(|_| Error::Invalid("issuer key"))?;
235	    require(
236	        a == atrium_crypto::Algorithm::P256
237	            && atrium_crypto::did::format_did_key(a, &k)
238	                .map_err(|_| Error::Invalid("issuer point"))?
239	                == s,
240	        "issuer key",
241	    )
242	}
243	
244	pub fn verify(input: Input<'_>, budget: Budget) -> Result<Member> {
245	    let ctx = input.context;
246	    require(matches!(ctx.profile, 2 | 3), "profile")?;
247	    did(&ctx.issuer)?;
248	    did(&ctx.observer)?;
249	    let count = input
250	        .records
251	        .len()
252	        .checked_add(input.membership.len())
253	        .and_then(|n| n.checked_add(input.objects.len()))
254	        .ok_or(Error::Budget)?;
255	    let mut work = Work::new(budget, count)?;
256	    let plan = match (ctx.profile, input.plan) {
257	        (2, None) => {
258	            require(input.membership.is_empty(), "profile2 membership")?;
259	            None
260	        }
261	        (3, Some(bytes)) => {
262	            work.input(bytes.len())?;
263	            let p = Plan::decode(bytes).map_err(|_| Error::Invalid("plan"))?;
264	            require(
265	                p.archive_id() == ctx.archive
266	                    && p.target().scope == ctx.scope
267	                    && p.target().issuer == ctx.issuer,
268	                "plan binding",
269	            )?;
270	            Some(p)
271	        }
272	        _ => return Err(Error::Invalid("profile plan")),
273	    };
274	    let mut keys = BTreeMap::<String, Coordinate>::new();
275	    let mut last = None;
276	    for m in input.membership {
277	        work.input(44)?;
278	        let k = key(m.cid)?;
279	        ordered(&mut last, &k)?;
280	        let mut c = coordinate(m.cid);
281	        length(&mut c, m.length)?;
282	        c.member = true;
283	        keys.insert(k, c);
284	    }
285	    let mut frontier = Frontier::default();
286	    let mut references = Vec::new();
287	    let mut writers = BTreeMap::<String, (u64, Cid)>::new();
288	    let mut operations = BTreeSet::new();
289	    let mut slots = BTreeMap::new();
290	    let mut source = Sha256::new();
291	    source.update(b"tools.kan.archive.copy-source.v1\0");
292	    work.frame(&mut source, b"commits")?;
293	    if let Some(p) = &plan {
294	        source.update(p.source().through.to_be_bytes())
295	    }
296	    for row in input.records {
297	        for (bytes, max) in [
298	            (row.manifest, 65536),
299	            (row.receipt, 65536),
300	            (row.proof, 16384),
301	        ] {
302	            require(!bytes.is_empty() && bytes.len() <= max, "metadata bounds")?;
303	            work.input(bytes.len())?;
304	        }
305	        require(row.sequence == frontier.through + 1, "record position")?;
306	        let m = known(row.manifest, Kind::Manifest)?;
307	        let r = known(row.receipt, Kind::Receipt)?;
308	        let p = proof::verify(
309	            row.proof,
310	            &proof::Context {
311	                issuer: &ctx.issuer,
312	                archive: ctx.archive,
313	                scope: ctx.scope,
314	            },
315	            &m,
316	            &r,
317	            &frontier,
318	        )
319	        .map_err(|_| Error::Invalid("issuer proof"))?;
320	        let retained = plan
321	            .as_ref()
322	            .is_some_and(|p| row.sequence <= p.source().through);
323	        require(
324	            p.purpose()
325	                == if retained {
326	                    Purpose::RetainedVerified
327	                } else {
328	                    Purpose::Admitted
329	                },
330	            "proof purpose",
331	        )?;
332	        if retained {
333	            let author = service::author(
334	                &plan
335	                    .as_ref()
336	                    .expect("retained plan")
337	                    .source()
338	                    .historical_issuer,
339	            )
340	            .map_err(|_| Error::Invalid("historical issuer"))?;
341	            require(r.body()["issuer"] == author, "historical receipt issuer")?;
342	        }
343	        let b = m.body();
344	        let wb = evidence::closed(
345	            &b["writer"],
346	            &["principal", "verificationMethod", "identityVersion"],
347	        )
348	        .map_err(|_| Error::Invalid("writer"))?;
349	        let writer =
350	            evidence::string(&wb["principal"], 80).map_err(|_| Error::Invalid("writer"))?;
351	        require(
352	            service::author(writer).map_err(|_| Error::Invalid("static writer"))? == b["writer"],
353	            "static writer",
354	        )?;
355	        let pos =
356	            evidence::uint(&b["position"]).map_err(|_| Error::Invalid("writer position"))? as u64;
357	        let expected = writers.get(writer);
358	        require(
359	            match expected {
360	                None => pos == 0 && b["previous"] == Ipld::Null,
361	                Some((old, cid)) => pos == old + 1 && b["previous"] == Ipld::Link(cid.clone()),
362	            },
363	            "writer predecessor",
364	        )?;
365	        let op = evidence::bytes(&b["operation"], 16).map_err(|_| Error::Invalid("operation"))?;
366	        require(
367	            operations.insert((writer.to_string(), op.to_vec())),
368	            "duplicate operation",
369	        )?;
370	        let Ipld::List(es) = &b["entries"] else {
371	            return Err(Error::Invalid("entries"));
372	        };
373	        require(es.len() == 1, "service request entry")?;
374	        let e = evidence::closed(&es[0], &["slot", "ciphertext", "length"])
375	            .map_err(|_| Error::Invalid("entry"))?;
376	        let cid =
377	            evidence::link(&e["ciphertext"], 0x55).map_err(|_| Error::Invalid("entry CID"))?;
378	        let n = evidence::uint(&e["length"]).map_err(|_| Error::Invalid("entry length"))? as u64;
379	        let k = key(cid)?;
380	        let c = keys.entry(k.clone()).or_insert_with(|| coordinate(cid));
381	        length(c, n)?;
382	        c.referenced = true;
383	        if retained {
384	            require(c.member, "retained reference absent from membership")?
385	        }
386	        let slot = evidence::bytes(&e["slot"], 32)
387	            .map_err(|_| Error::Invalid("slot"))?
388	            .to_vec();
389	        let expected_slot: [u8; 32] = Sha256::digest(op).into();
390	        require(slot.as_slice() == expected_slot, "service slot")?;
391	        let sk = (writer.to_string(), slot);
392	        let sv = (k.clone(), n);
393	        require(
394	            slots.get(&sk).is_none_or(|old| old == &sv),
395	            "conflicting slot binding",
396	        )?;
397	        slots.insert(sk, sv);
398	        if retained {
399	            source.update(row.sequence.to_be_bytes());
400	            work.frame(&mut source, row.manifest)?;
401	            work.frame(&mut source, row.receipt)?;
402	            work.frame(&mut source, &cid.to_bytes())?;
403	            let plan = plan.as_ref().expect("retained plan");
404	            if row.sequence == plan.source().through {
405	                require(plan.source().tip.as_ref() == Some(m.cid()), "source tip")?
406	            }
407	        }
408	        writers.insert(writer.to_string(), (pos, m.cid().clone()));
409	        references.push((row.sequence, k));
410	        frontier = p.frontier().clone();
411	        work.check()?;
412	    }
413	    let recipe_metadata_complete = if let Some(p) = &plan {
414	        work.frame(&mut source, b"objects")?;
415	        source.update((input.membership.len() as u64).to_be_bytes());
416	        for m in input.membership {
417	            work.check()?;
418	            work.frame(&mut source, &m.cid.to_bytes())?;
419	            source.update(m.length.to_be_bytes())
420	        }
421	        let digest: [u8; 32] = source.finalize().into();
422	        let full = frontier.through >= p.source().through;
423	        if full {
424	            require(digest == p.source().digest, "source metadata digest")?
425	        }
426	        full
427	    } else {
428	        true
429	    };
430	    last = None;
431	    for (index, object) in input.objects.iter().enumerate() {
432	        require(
433	            object.bytes.len() <= MAX_OBJECT,
434	            "forensic-recovery-required",
435	        )?;
436	        work.input(object.bytes.len())?;
437	        let k = key(object.cid)?;
438	        ordered(&mut last, &k)?;
439	        let c = keys.entry(k).or_insert_with(|| coordinate(object.cid));
440	        if !recipe_metadata_complete {
441	            require(c.member, "untracked object in partial copy")?
442	        }
443	        c.original = Some(index);
444	        let mut hash = Sha256::new();
445	        work.hash(&mut hash, object.bytes)?;
446	        let actual: [u8; 32] = hash.finalize().into();
447	        let valid = !object.bytes.is_empty()
448	            && c.length.is_none_or(|n| n == object.bytes.len() as u64)
449	            && actual == object.cid.to_bytes()[4..];
450	        c.state = if valid {
451	            Availability::Available
452	        } else {
453	            Availability::Corrupt
454	        };
455	    }
456	    let mut losses = Vec::new();
457	    let mut verified_requests = 0;
458	    for ((sequence, k), row) in references.iter().zip(input.records) {
459	        work.check()?;
460	        let c = &keys[k];
461	        if c.state == Availability::Available {
462	            let committed = Committed {
463	                sequence: *sequence,
464	                manifest: known(row.manifest, Kind::Manifest)?,
465	                receipt: known(row.receipt, Kind::Receipt)?,
466	                duplicate: false,
467	            };
468	            service::verify_retained_request(
469	                &committed,
470	                input.objects[c.original.expect("available original")].bytes,
471	            )
472	            .map_err(|_| Error::Invalid("retained writer request"))?;
473	            verified_requests += 1;
474	        } else {
475	            losses.push(Loss {
476	                occurrence: Some(*sequence),
477	                cid: c.cid.clone(),
478	                expected_length: c.length,
479	                state: c.state,
480	            })
481	        }
482	    }
483	    for c in keys.values() {
484	        work.check()?;
485	        if !c.referenced && c.state != Availability::Available {
486	            losses.push(Loss {
487	                occurrence: None,
488	                cid: c.cid.clone(),
489	                expected_length: c.length,
490	                state: c.state,
491	            })
492	        }
493	    }
494	    work.check()?;
495	    let framing_bytes = work
496	        .bytes
497	        .checked_mul(4)
498	        .and_then(|n| n.checked_add((count as u64).checked_mul(128)?))
499	        .and_then(|n| n.checked_add(1024))
500	        .ok_or(Error::Budget)?;
501	    let limits = Limits {
502	        items: count as u64,
503	        bytes: framing_bytes,
504	        duration: work.deadline.saturating_duration_since(Instant::now()),
505	        cancelled: work.budget.cancelled.clone(),
506	    };
507	    if limits.duration.is_zero() {
508	        return Err(Error::Budget);
509	    }
510	    let mut framing = MemberFraming::new(
511	        Header {
512	            profile: ctx.profile,
513	            archive: ctx.archive,
514	            scope: ctx.scope,
515	            issuer: &ctx.issuer,
516	            plan: input.plan,
517	        },
518	        Counts {
519	            membership: input.membership.len() as u64,
520	            records: input.records.len() as u64,
521	            objects: input.objects.len() as u64,
522	        },
523	        Domain::Member,
524	        limits,
525	    )
526	    .map_err(framing_error)?;
527	    for m in input.membership {
528	        framing.membership(m.cid, m.length).map_err(framing_error)?
529	    }
530	    framing.begin_records().map_err(framing_error)?;
531	    for r in input.records {
532	        framing
533	            .record(r.sequence, r.manifest, r.receipt, r.proof)
534	            .map_err(framing_error)?
535	    }
536	    framing.begin_objects().map_err(framing_error)?;
537	    for o in input.objects {
538	        framing
539	            .original_object(o.cid, o.bytes)
540	            .map_err(framing_error)?
541	    }
542	    let commitment = framing.finish().map_err(framing_error)?;
543	    work.check()?;
544	    Ok(Member {
545	        context: ctx.clone(),
546	        commitment,
547	        frontier,
548	        recipe_metadata_complete,
549	        losses,
550	        verified_requests,
551	    })
552	}
