122	// Caller owns a pinned transaction and has fully verified payloads/base metadata.
123	// Partial source-copy status is not proof that a prefix matches an unavailable
124	// source; resumption additionally compares it against the audited PlannedCopy.
125	pub(super) fn audit(
126	    ledger: &Ledger,
127	    binding: &attested::Binding,
128	    plan: &Plan,
129	    base: &super::Verification,
130	) -> Result<Status> {
131	    ledger.check_profile(3)?;
132	    audit_state(
133	        &ledger.conn,
134	        binding,
135	        plan,
136	        base.snapshot.through,
137	        base.objects,
138	    )
139	}
140	fn audit_state(
141	    conn: &Connection,
142	    binding: &attested::Binding,
143	    plan: &Plan,
144	    through: u64,
145	    objects: u64,
146	) -> Result<Status> {
147	    check_plan(conn, binding, plan)?;
148	    let copied_records = through.min(plan.source().through);
149	    let mut hash = Sha256::new();
150	    hash.update(SOURCE_DOMAIN);
151	    frame(&mut hash, b"commits");
152	    hash.update(plan.source().through.to_be_bytes());
153	    for sequence in 1..=copied_records {
154	        let row = attested::record(conn, sequence)?;
155	        let es: Vec<_> = entries(&row.manifest).collect();
156	        if es.len() != 1 {
157	            return Err(corrupt("copy request entry"));
158	        }
