1	//! Streaming recovery framing commitments. A digest is not a verified member.
2	//!
3	//! Inputs must already be acquired under caller authority and read budgets. This
4	//! layer bounds its own work, checks framing/order/local sizes and hashes bytes;
5	//! it does not check record signatures, copy-plan truth or publication readiness.
6	use atproto_dasl::Cid;
7	use sha2::{Digest, Sha256};
8	use std::{
9	    sync::{
10	        atomic::{AtomicBool, Ordering},
11	        Arc,
12	    },
13	    time::{Duration, Instant},
14	};
15	
16	const SAFE: u64 = 9_007_199_254_740_991;
17	const MAX_OBJECT: usize = 4 * 1024 * 1024;
18	type Result<T> = std::result::Result<T, Error>;
19	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
20	pub enum Error {
21	    #[error("invalid recovery commitment framing: {0}")]
22	    Shape(&'static str),
23	    #[error("recovery commitment work budget exhausted")]
24	    Budget,
25	    #[error("recovery commitment cancelled")]
26	    Cancelled,
27	    #[error("recovery commitment builder previously failed")]
28	    Poisoned,
29	}
30	fn shape(ok: bool, reason: &'static str) -> Result<()> {
31	    if ok {
32	        Ok(())
33	    } else {
34	        Err(Error::Shape(reason))
35	    }
36	}
37	
38	/// Caller-selected work limits, not archive format size ceilings. Byte budget
39	/// counts framing and hashing work; candidate verification hashes bytes twice.
40	#[derive(Clone)]
41	pub struct Limits {
42	    pub items: u64,
43	    pub bytes: u64,
44	    pub duration: Duration,
45	    pub cancelled: Arc<AtomicBool>,
46	}
47	#[derive(Clone, Copy)]
48	pub struct Counts {
49	    pub membership: u64,
50	    pub records: u64,
51	    pub objects: u64,
52	}
53	#[derive(Clone, Copy)]
54	pub enum Domain {
55	    Member,
56	    Output,
57	}
58	pub struct Header<'a> {
59	    pub profile: u8,
60	    pub archive: [u8; 32],
61	    pub scope: [u8; 32],
62	    pub issuer: &'a str,
63	    pub plan: Option<&'a [u8]>,
64	}
65	struct Meter {
66	    limits: Limits,
67	    deadline: Instant,
68	    bytes: u64,
69	    items: u64,
70	    // Test-only cancellation injection after charged bytes, without timing sleeps.
71	    #[cfg(test)]
72	    cancel_after_bytes: std::cell::Cell<Option<u64>>,
73	}
74	impl Meter {
75	    fn new(limits: Limits, items: u64) -> Result<Self> {
76	        shape(
77	            !limits.duration.is_zero() && limits.duration <= Duration::from_secs(3600),
78	            "duration",
79	        )?;
80	        if items > limits.items {
81	            return Err(Error::Budget);
82	        }
83	        let deadline = Instant::now()
84	            .checked_add(limits.duration)
85	            .ok_or(Error::Budget)?;
86	        let out = Self {
87	            limits,
88	            deadline,
89	            bytes: 0,
90	            items: 0,
91	            #[cfg(test)]
92	            cancel_after_bytes: std::cell::Cell::new(None),
93	        };
94	        out.check()?;
95	        Ok(out)
96	    }
97	    fn check(&self) -> Result<()> {
98	        #[cfg(test)]
99	        if self
100	            .cancel_after_bytes
101	            .get()
102	            .is_some_and(|limit| self.bytes >= limit)
103	        {
104	            self.limits.cancelled.store(true, Ordering::Relaxed);
105	        }
106	        if self.limits.cancelled.load(Ordering::Relaxed) {
107	            return Err(Error::Cancelled);
108	        }
109	        if Instant::now() >= self.deadline {
110	            return Err(Error::Budget);
111	        }
112	        Ok(())
113	    }
114	    fn spend(&mut self, bytes: usize) -> Result<()> {
115	        self.check()?;
116	        self.bytes = self.bytes.checked_add(bytes as u64).ok_or(Error::Budget)?;
117	        if self.bytes > self.limits.bytes {
118	            return Err(Error::Budget);
119	        }
120	        Ok(())
121	    }
122	    fn item(&mut self) -> Result<()> {
123	        self.check()?;
124	        self.items = self.items.checked_add(1).ok_or(Error::Budget)?;
125	        if self.items > self.limits.items {
126	            return Err(Error::Budget);
127	        }
128	        Ok(())
129	    }
130	}
131	struct Core {
132	    hash: Sha256,
133	    meter: Meter,
134	    failed: bool,
135	}
136	impl Core {
137	    fn new(domain: &[u8], limits: Limits, items: u64) -> Result<Self> {
138	        let mut out = Self {
139	            hash: Sha256::new(),
140	            meter: Meter::new(limits, items)?,
141	            failed: false,
142	        };
143	        out.put(domain)?;
144	        Ok(out)
145	    }
146	    fn put(&mut self, bytes: &[u8]) -> Result<()> {
147	        self.meter.check()?;
148	        for part in bytes.chunks(64 * 1024) {
149	            self.meter.spend(part.len())?;
150	            self.hash.update(part)
151	        }
152	        Ok(())
153	    }
154	    fn n(&mut self, n: u64) -> Result<()> {
155	        self.put(&n.to_be_bytes())
156	    }
157	    fn frame(&mut self, b: &[u8]) -> Result<()> {
158	        self.n(b.len() as u64)?;
159	        self.put(b)
160	    }
161	    fn finish(self) -> Result<[u8; 32]> {
162	        if self.failed {
163	            return Err(Error::Poisoned);
164	        }
165	        self.meter.check()?;
166	        Ok(self.hash.finalize().into())
167	    }
168	}
169	fn raw_key(cid: &Cid) -> Result<(String, Vec<u8>)> {
170	    let raw = cid.to_bytes();
171	    shape(
172	        raw.len() == 36 && raw[..4] == [1, 0x55, 0x12, 0x20],
173	        "object CID",
174	    )?;
175	    Ok((cid.to_string(), raw))
176	}
177	fn ordered(last: &mut Option<String>, next: String) -> Result<()> {
178	    shape(
179	        last.as_ref().is_none_or(|old| old < &next),
180	        "duplicate or unordered CID",
181	    )?;
182	    *last = Some(next);
183	    Ok(())
184	}
185	#[derive(Clone, Copy, PartialEq, Eq)]
186	enum Phase {
187	    Membership,
188	    Records,
189	    Objects,
190	}
191	/// Strictly ordered streaming input. Any rejected operation poisons the builder,
192	/// so ignoring an error cannot produce a digest of a silently shortened member.
193	pub struct MemberFraming {
194	    core: Core,
195	    counts: Counts,
196	    phase: Phase,
197	    seen: u64,
198	    last: Option<String>,
199	}
200	impl MemberFraming {
201	    pub fn new(header: Header<'_>, counts: Counts, domain: Domain, limits: Limits) -> Result<Self> {
202	        shape(matches!(header.profile, 2 | 3), "profile")?;
203	        shape(
204	            !header.issuer.is_empty() && header.issuer.len() <= 80,
205	            "issuer length",
206	        )?;
207	        for count in [counts.membership, counts.records, counts.objects] {
208	            shape(count <= SAFE, "count")?
209	        }
210	        let total = counts
211	            .membership
212	            .checked_add(counts.records)
213	            .and_then(|n| n.checked_add(counts.objects))
214	            .ok_or(Error::Budget)?;
215	        if header.profile == 2 {
216	            shape(
217	                header.plan.is_none() && counts.membership == 0,
218	                "profile2 plan",
219	            )?
220	        } else {
221	            shape(
222	                header
223	                    .plan
224	                    .is_some_and(|p| !p.is_empty() && p.len() <= 4096),
225	                "profile3 plan",
226	            )?
227	        }
228	        let domain = match domain {
229	            Domain::Member => b"tools.kan.recovery.member.v1\0".as_slice(),
230	            Domain::Output => b"tools.kan.recovery.output.v1\0".as_slice(),
231	        };
232	        let mut core = Core::new(domain, limits, total)?;
233	        core.n(header.profile.into())?;
234	        core.frame(&header.archive)?;
235	        core.frame(&header.scope)?;
236	        core.frame(header.issuer.as_bytes())?;
237	        core.frame(b"plan")?;
238	        core.n(u64::from(header.plan.is_some()))?;
239	        if let Some(plan) = header.plan {
240	            core.frame(plan)?
241	        }
242	        core.frame(b"original-membership")?;
243	        core.n(counts.membership)?;
244	        Ok(Self {
245	            core,
246	            counts,
247	            phase: Phase::Membership,
248	            seen: 0,
249	            last: None,
250	        })
251	    }
252	    fn operation(&mut self, operation: impl FnOnce(&mut Self) -> Result<()>) -> Result<()> {
253	        if self.core.failed {
254	            return Err(Error::Poisoned);
255	        }
256	        self.core.failed = true;
257	        let result = operation(self);
258	        if result.is_ok() {
259	            self.core.failed = false
260	        }
261	        result
262	    }
263	    pub fn membership(&mut self, cid: &Cid, length: u64) -> Result<()> {
264	        self.operation(|s| {
265	            shape(
266	                s.phase == Phase::Membership && s.seen < s.counts.membership,
267	                "membership position",
268	            )?;
269	            shape(
270	                (1..=MAX_OBJECT as u64).contains(&length),
271	                "membership length",
272	            )?;
273	            let (name, key) = raw_key(cid)?;
274	            ordered(&mut s.last, name)?;
275	            s.core.meter.item()?;
276	            s.core.frame(&key)?;
277	            s.core.n(length)?;
278	            s.seen += 1;
279	            Ok(())
280	        })
281	    }
282	    pub fn begin_records(&mut self) -> Result<()> {
283	        self.operation(|s| {
284	            shape(
285	                s.phase == Phase::Membership && s.seen == s.counts.membership,
286	                "incomplete membership",
287	            )?;
288	            s.core.frame(b"records")?;
289	            s.core.n(s.counts.records)?;
290	            s.phase = Phase::Records;
291	            s.seen = 0;
292	            s.last = None;
293	            Ok(())
294	        })
295	    }
296	    pub fn record(
297	        &mut self,
298	        sequence: u64,
299	        manifest: &[u8],
300	        receipt: &[u8],
301	        proof: &[u8],
302	    ) -> Result<()> {
303	        self.operation(|s| {
304	            shape(
305	                s.phase == Phase::Records && s.seen < s.counts.records && sequence == s.seen + 1,
306	                "record position",
307	            )?;
308	            for (bytes, max) in [(manifest, 65536), (receipt, 65536), (proof, 16384)] {
309	                shape(!bytes.is_empty() && bytes.len() <= max, "record bytes")?
310	            }
311	            s.core.meter.item()?;
312	            s.core.n(sequence)?;
313	            s.core.frame(manifest)?;
314	            s.core.frame(receipt)?;
315	            s.core.frame(proof)?;
316	            s.seen += 1;
317	            Ok(())
318	        })
319	    }
320	    pub fn begin_objects(&mut self) -> Result<()> {
321	        self.operation(|s| {
322	            shape(
323	                s.phase == Phase::Records && s.seen == s.counts.records,
324	                "incomplete records",
325	            )?;
326	            s.core.frame(b"original-objects")?;
327	            s.core.n(s.counts.objects)?;
328	            s.phase = Phase::Objects;
329	            s.seen = 0;
330	            s.last = None;
331	            Ok(())
332	        })
333	    }
334	    pub fn original_object(&mut self, cid: &Cid, bytes: &[u8]) -> Result<()> {
335	        self.operation(|s| {
336	            shape(
337	                s.phase == Phase::Objects && s.seen < s.counts.objects,
338	                "object position",
339	            )?;
340	            shape(bytes.len() <= MAX_OBJECT, "object bytes")?;
341	            let (name, key) = raw_key(cid)?;
342	            ordered(&mut s.last, name)?;
343	            s.core.meter.item()?;
344	            s.core.frame(&key)?;
345	            s.core.n(bytes.len() as u64)?;
346	            s.core.frame(bytes)?;
347	            s.seen += 1;
348	            Ok(())
349	        })
350	    }
351	    pub fn finish(self) -> Result<[u8; 32]> {
352	        if self.core.failed {
353	            return Err(Error::Poisoned);
354	        }
355	        shape(
356	            self.phase == Phase::Objects && self.seen == self.counts.objects,
357	            "incomplete objects",
358	        )?;
359	        self.core.finish()
360	    }
361	}
362	/// R1 framing also verifies candidate content addresses. It still does not prove
363	/// candidate membership, historical selection or a restoration observation.
364	pub struct RestorationFraming {
365	    core: Core,
366	    count: u64,
367	    seen: u64,
368	    last: Option<String>,
369	}
370	impl RestorationFraming {
