302	fn map(value: &Ipld) -> Result<&BTreeMap<String, Ipld>, Error> {
303	    if let Ipld::Map(value) = value {
304	        Ok(value)
305	    } else {
306	        Err(fail("expected map"))
307	    }
308	}
309	
310	pub(crate) fn closed<'a>(
311	    value: &'a Ipld,
312	    fields: &[&str],
313	) -> Result<&'a BTreeMap<String, Ipld>, Error> {
314	    let value = map(value)?;
315	    if value.len() != fields.len() || fields.iter().any(|field| !value.contains_key(*field)) {
316	        return Err(fail("missing or unknown field"));
317	    }
318	    Ok(value)
319	}
320	
321	pub(crate) fn uint(value: &Ipld) -> Result<i128, Error> {
322	    match value {
323	        Ipld::Integer(n) if (0..=MAX_SAFE_INTEGER).contains(n) => Ok(*n),
324	        _ => Err(fail("expected unsigned safe integer")),
325	    }
326	}
327	
328	pub(crate) fn bytes(value: &Ipld, length: usize) -> Result<&[u8], Error> {
329	    match value {
330	        Ipld::Bytes(value) if value.len() == length => Ok(value),
331	        _ => Err(fail("wrong byte string length")),
332	    }
333	}
334	
335	pub(crate) fn string(value: &Ipld, max: usize) -> Result<&str, Error> {
336	    match value {
337	        Ipld::String(value) if !value.is_empty() && value.len() <= max => Ok(value),
338	        _ => Err(fail("wrong string length or type")),
339	    }
340	}
341	
342	fn token(value: &Ipld) -> Result<&str, Error> {
343	    let value = string(value, 64)?;
344	    if !value.as_bytes()[0].is_ascii_lowercase()
345	        || !value
346	            .bytes()
347	            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'.' || b == b'-')
348	    {
349	        return Err(fail("invalid protocol token"));
350	    }
351	    Ok(value)
352	}
353	
354	fn list(value: &Ipld) -> Result<&[Ipld], Error> {
355	    match value {
356	        Ipld::List(value) if value.len() <= 128 => Ok(value),
357	        _ => Err(fail("expected list of at most 128 items")),
358	    }
359	}
360	
361	pub(crate) fn link(value: &Ipld, codec: u8) -> Result<&Cid, Error> {
362	    if let Ipld::Link(cid) = value {
363	        let raw = cid.to_bytes();
364	        if raw.len() == 36 && raw[..4] == [1, codec, 0x12, 0x20] {
365	            return Ok(cid);
366	        }
367	    }
368	    Err(fail("wrong CID profile"))
369	}
370	
371	pub(crate) fn author(value: &Ipld) -> Result<(), Error> {
372	    // Preserve the strict parser's types through the identity boundary. Generic
373	    // drisl IPLD deserialization can reinterpret untagged bytes as a CID.
374	    let fields = closed(
375	        value,
376	        &["principal", "verificationMethod", "identityVersion"],
377	    )?;
378	    let version = closed(&fields["identityVersion"], &["kind", "value"])?;
379	    let identity = match (&version["kind"], &version["value"]) {
380	        (Ipld::String(kind), Ipld::Null) if kind == "static" => IdentityVersion::Static,
381	        (Ipld::String(kind), Ipld::Link(cid)) if kind == "event" => {
382	            IdentityVersion::Event(cid.clone())
383	        }
384	        (Ipld::String(kind), Ipld::Link(cid)) if kind == "documentCid" => {
385	            IdentityVersion::DocumentCid(cid.clone())
386	        }
387	        (Ipld::String(kind), Ipld::String(id)) if kind == "versionId" && !id.is_empty() => {
388	            IdentityVersion::VersionId(id.clone())
389	        }
390	        _ => return Err(fail("invalid identity version shape")),
391	    };
392	    Author::new(
393	        string(&fields["principal"], MAX_RECORD_BYTES)?.into(),
394	        string(&fields["verificationMethod"], MAX_RECORD_BYTES)?.into(),
395	        identity,
396	    )
397	    .map_err(|e| Error::Schema(e.to_string()))?;
398	    Ok(())
399	}
400	
401	fn chain(position: &Ipld, previous: &Ipld) -> Result<(), Error> {
402	    if uint(position)? == 0 {
403	        if !matches!(previous, Ipld::Null) {
404	            return Err(fail("genesis has predecessor"));
405	        }
406	    } else {
407	        link(previous, 0x71)?;
408	    }
409	    Ok(())
410	}
411	
412	fn capture(value: &Ipld) -> Result<(), Error> {
413	    let b = closed(
414	        value,
415	        &[
416	            "observer",
417	            "scope",
418	            "stream",
419	            "sequence",
420	            "previous",
421	            "occurredAt",
422	            "eventType",
423	            "payloads",
424	            "parents",
425	            "coverage",
426	        ],
427	    )?;
428	    author(&b["observer"])?;
429	    let scope: [u8; 34] = bytes(&b["scope"], 34)?.try_into().expect("checked length");
430	    ScopeId::from_bytes(scope).map_err(|e| Error::Schema(e.to_string()))?;
431	    bytes(&b["stream"], 16)?;
432	    chain(&b["sequence"], &b["previous"])?;
433	    uint(&b["occurredAt"])?;
434	    token(&b["eventType"])?;
435	    for payload in list(&b["payloads"])? {
436	        let p = closed(payload, &["sha256", "length", "mediaType"])?;
437	        bytes(&p["sha256"], 32)?;
438	        uint(&p["length"])?;
439	        string(&p["mediaType"], 256)?;
440	    }
441	    let mut seen = BTreeSet::new();
442	    for parent in list(&b["parents"])? {
443	        if !seen.insert(link(parent, 0x71)?.to_bytes()) {
444	            return Err(fail("duplicate parent"));
445	        }
446	    }
447	    let coverage = closed(&b["coverage"], &["complete", "missing"])?;
448	    let missing = list(&coverage["missing"])?;
449	    let mut previous = None;
450	    for reason in missing {
451	        let reason = token(reason)?;
452	        if previous.is_some_and(|p| p >= reason) {
453	            return Err(fail("unsorted or duplicate coverage reasons"));
454	        }
455	        previous = Some(reason);
456	    }
457	    if coverage["complete"] != Ipld::Bool(missing.is_empty()) {
458	        return Err(fail("inconsistent coverage"));
459	    }
460	    Ok(())
461	}
462	
463	fn manifest(value: &Ipld) -> Result<(), Error> {
464	    let b = closed(
465	        value,
466	        &[
467	            "writer",
468	            "scopeToken",
469	            "operation",
470	            "position",
471	            "previous",
472	            "entries",
473	        ],
474	    )?;
475	    author(&b["writer"])?;
476	    bytes(&b["scopeToken"], 32)?;
477	    bytes(&b["operation"], 16)?;
478	    chain(&b["position"], &b["previous"])?;
479	    let entries = list(&b["entries"])?;
480	    if entries.is_empty() {
481	        return Err(fail("empty manifest"));
482	    }
