            ("issuer", author(issuer)),
            ("manifest", Ipld::Link(m.cid().clone())),
            ("scopeToken", b["scopeToken"].clone()),
            ("operation", b["operation"].clone()),
            ("position", b["position"].clone()),
            ("durability", Ipld::String("remote-durable".into())),
