fn entry_cid(manifest: &[u8]) -> (Cid, u64) {
    let m = decode(manifest);
    let Ipld::List(es) = &m.body()["entries"] else {
        panic!()
    };
    let Ipld::Map(e) = &es[0] else { panic!() };
    let Ipld::Link(c) = &e["ciphertext"] else {
        panic!()
    };
