    target_issuer: Option<String>,
}
impl Default for Opts {
    fn default() -> Self {
        Opts {
            profile: 2,
            n: 2,
            current_receipts: false,
            staged: vec![],
            tip_index: None,
            target_scope: None,
            target_issuer: None,
        }
