        (
            "event-version",
            map([
                ("principal", Ipld::String(writer.clone())),
                ("verificationMethod", Ipld::String(format!("{writer}#{}", &writer[8..]))),
                ("identityVersion", map([("kind", Ipld::String("event".into())), ("value", Ipld::Link(ciphertext_cid(b"e")))])),
