/// RP12: cross-scope/issuer owner context and observer DID validation.
#[test]
fn rp12_cross_scope_issuer_and_observer() {
    let mut f = build(Opts { profile: 2, n: 1, ..Default::default() });
    f.context.scope = [9; 32];
    let r = run(&f, budget());
